// ============================================================================
// LEAD RULES: the node for what THIS business accepts and how names are matched. DATA ONLY (no logic).
// Edit the values between the EDIT lines. Every lead is checked against it, and a mistake gives a
// clear 500 (intake_misconfigured, lines start "Rules:") before anything is claimed or written.
// What you cannot change here, on purpose: the base required fields, exact-email matching, the
// scoring maths and thresholds (CONFIG), "never overwrite a filled CRM field", the claim/replay logic.
// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
const rules = {
  // Email domains you refuse outright (the caller gets 422 lead_rejected and nothing is stored).
  blocked_email_domains: [],
  // Email domains whose NEW records are created but flagged for a human (needs_review, reason "review_domain").
  review_email_domains: [],
  // Request fields that must be present as well as the basics: title, phone, linkedin_url (400 if missing).
  require: [],
  // Extra request fields to pass to the CRM (text up to 300 characters). They are saved on new
  // records, and on a merge they only fill an EMPTY CRM field; a different value is reported as a conflict.
  custom_fields: [],
  // Words ignored at the end of company names, added to the built-in list (inc, llc, ltd, gmbh ...).
  company_suffixes: [],
  // Nickname -> formal first name, added to CONFIG.NICKNAMES_JSON (these win).
  nicknames: {},
  // How a lead is compared with CRM contacts. (The thresholds and the name/company weights stay in CONFIG.)
  matching: {
    // Titles ignored in front of a first name, added to the built-in dr mr mrs ms miss mx prof.
    name_prefixes: [],
    // Words ignored after a last name, added to the built-in jr sr ii iii iv phd md.
    name_suffixes: [],
    // true = also compare with the contact's first and last name swapped, and keep the better score.
    swap_first_last: false,
    // null = compare the whole name as one piece. { first: 0.3, last: 0.7 } = score first and last name separately, with these weights.
    name_weights: null,
    // Short company names -> the full name. Lower case, written as names look once "inc", "ltd" etc. are removed: { fb: 'facebook' }
    company_aliases: {},
    // Placeholder companies that never count as evidence of a match. Lower case, punctuation as spaces ("n/a" is 'n a').
    unknown_companies: [],
  },
};
// ---- STOP EDITING HERE ------------------------------------------------------
const pick = (o, k, d) => (o && o[k] !== undefined && o[k] !== null ? o[k] : d);
const rawM = rules && rules.matching !== undefined && rules.matching !== null ? rules.matching : {};
const mObj = rawM !== null && typeof rawM === 'object' && !Array.isArray(rawM);
const matching = { name_prefixes: pick(rawM, 'name_prefixes', []), name_suffixes: pick(rawM, 'name_suffixes', []), swap_first_last: pick(rawM, 'swap_first_last', false), name_weights: pick(rawM, 'name_weights', null),
  company_aliases: pick(rawM, 'company_aliases', {}), unknown_companies: pick(rawM, 'unknown_companies', []), _is_obj: mObj, _raw_keys: mObj ? Object.keys(rawM) : [] };
const norm = { blocked_email_domains: pick(rules, 'blocked_email_domains', []), review_email_domains: pick(rules, 'review_email_domains', []), require: pick(rules, 'require', []),
  custom_fields: pick(rules, 'custom_fields', []), company_suffixes: pick(rules, 'company_suffixes', []), nicknames: pick(rules, 'nicknames', {}), matching,
  _is_obj: rules !== null && typeof rules === 'object' && !Array.isArray(rules), _raw_keys: Object.keys(rules || {}) };
return [{ json: { ...$input.first().json, rules: norm } }];

const C = $('CONFIG').first().json;
const req = $('Intake Webhook').first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const reject = (status, error, details) => [{ json: { ok: false, http_status: status, response_body: { error, ...(details ? { details } : {}) }, notifications: [] } }];

if (C.INTAKE_AUTH_TOKEN && (req.headers || {})['x-intake-token'] !== C.INTAKE_AUTH_TOKEN) return reject(401, 'unauthorized');

// ---- CONFIG sanity: a typo here should say so, not fail three nodes later
const bad = [];
for (const k of ['LEAD_STORE_API_URL', 'ENRICHMENT_API_URL', 'CRM_API_URL']) if (!/^https?:\/\//.test(C[k] || '')) bad.push(`CONFIG.${k} must start with http:// or https://`);
if (C.SLACK_WEBHOOK_URL && !/^https?:\/\//.test(C.SLACK_WEBHOOK_URL)) bad.push('CONFIG.SLACK_WEBHOOK_URL must be blank or start with http(s)://');
for (const k of ['SERVICE_HEADERS_JSON', 'ENRICHMENT_HEADERS_JSON']) { try { if (!isObj(JSON.parse(C[k] || '{}'))) throw 0; } catch (e) { bad.push(`CONFIG.${k} must be a JSON object`); } }
try { const m = JSON.parse(C.NICKNAMES_JSON || '{}'); if (!isObj(m) || Object.values(m).some((v) => typeof v !== 'string')) throw 0; } catch (e) { bad.push('CONFIG.NICKNAMES_JSON must be a JSON object of nickname -> formal name'); }
const num = (k) => Number(C[k]);
if (!(num('REVIEW_THRESHOLD') > 0 && num('REVIEW_THRESHOLD') <= num('AUTO_MERGE_THRESHOLD') && num('AUTO_MERGE_THRESHOLD') <= 1)) bad.push('CONFIG thresholds must satisfy 0 < REVIEW_THRESHOLD <= AUTO_MERGE_THRESHOLD <= 1');
if (!(num('NAME_WEIGHT') >= 0 && num('COMPANY_WEIGHT') >= 0 && num('NAME_WEIGHT') + num('COMPANY_WEIGHT') > 0)) bad.push('CONFIG.NAME_WEIGHT and COMPANY_WEIGHT must be >= 0 and not both 0');
if (!['flag', 'reject'].includes(C.SEARCH_FAILURE_MODE)) bad.push("CONFIG.SEARCH_FAILURE_MODE must be 'flag' or 'reject'");
for (const k of ['PROCESSING_TTL_SECONDS', 'IDEMPOTENCY_TTL_SECONDS', 'REQUEST_TIMEOUT_MS', 'ENRICHMENT_TIMEOUT_MS']) if (!(num(k) > 0)) bad.push(`CONFIG.${k} must be a number > 0`);
// ---- the Lead Rules node
{
  const R = $('Lead Rules').first().json.rules;
  const rb = (m) => bad.push('Rules: ' + m);
  const list = (v, max, f) => Array.isArray(v) && v.length <= max && v.every(f) && new Set(v).size === v.length;
  const domain = (x) => typeof x === 'string' && /^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?\.[a-z]{2,}$/.test(x);
  const RESERVED = ['id', 'external_ref', 'first_name', 'last_name', 'email', 'secondary_email', 'company', 'title', 'phone', 'linkedin_url', 'source', 'industry', 'company_size', 'needs_review', 'review_reason', 'possible_duplicate_of', 'match_score', 'company_mismatch', 'enriched_company'];
  if (!R._is_obj) rb('rules must be an object');
  else {
    for (const k of R._raw_keys) if (!['blocked_email_domains', 'review_email_domains', 'require', 'custom_fields', 'company_suffixes', 'nicknames', 'matching'].includes(k)) rb(`${k} is not a known setting (blocked_email_domains, review_email_domains, require, custom_fields, company_suffixes, nicknames, matching)`);
    for (const k of ['blocked_email_domains', 'review_email_domains']) if (!list(R[k], 200, domain)) rb(`${k} must be a list of different lower-case domains such as "example.com"`);
    if (!list(R.require, 10, (x) => ['title', 'phone', 'linkedin_url'].includes(x) || (Array.isArray(R.custom_fields) && R.custom_fields.includes(x)))) rb('require must be a list of title, phone, linkedin_url or a name from custom_fields');
    if (!list(R.custom_fields, 20, (x) => typeof x === 'string' && /^[a-z][a-z0-9_]{0,39}$/.test(x) && !RESERVED.includes(x))) rb('custom_fields must be a list of at most 20 different names (lower-case letters, digits, _), none of the built-in field names');
    if (!list(R.company_suffixes, 100, (x) => typeof x === 'string' && /^[a-z0-9]{1,30}$/.test(x))) rb('company_suffixes must be a list of single lower-case words');
    {
      const M = R.matching;
      if (!M._is_obj) rb('matching must be an object');
      else {
        for (const k of M._raw_keys) if (!['name_prefixes', 'name_suffixes', 'swap_first_last', 'name_weights', 'company_aliases', 'unknown_companies'].includes(k)) rb(`matching.${k} is not a known setting (name_prefixes, name_suffixes, swap_first_last, name_weights, company_aliases, unknown_companies)`);
        for (const k of ['name_prefixes', 'name_suffixes']) if (!list(M[k], 50, (x) => typeof x === 'string' && /^[a-z]{1,20}$/.test(x))) rb(`matching.${k} must be a list of at most 50 different single lower-case words`);
        if (typeof M.swap_first_last !== 'boolean') rb('matching.swap_first_last must be true or false');
        const w = M.name_weights;
        if (w !== null && !(isObj(w) && Object.keys(w).sort().join() === 'first,last' && [w.first, w.last].every((x) => typeof x === 'number' && x >= 0 && x <= 1000) && w.first + w.last > 0)) rb('matching.name_weights must be null or { first, last } with two numbers from 0 to 1000 that are not both 0');
        const nm = (x) => typeof x === 'string' && /^[a-z0-9]+( [a-z0-9]+)*$/.test(x) && x.length <= 60;
        const A = M.company_aliases;
        if (!isObj(A) || Object.keys(A).length > 200 || Object.entries(A).some(([k, v]) => !nm(k) || !nm(v) || k === v || Object.prototype.hasOwnProperty.call(A, v))) rb('matching.company_aliases must be an object of at most 200 lower-case alias -> lower-case company name (letters, digits, single spaces); an alias may not map to itself or to another alias');
        if (!list(M.unknown_companies, 50, nm)) rb('matching.unknown_companies must be a list of at most 50 different lower-case names (letters, digits, single spaces; punctuation written as a space)');
      }
    }
    if (!isObj(R.nicknames) || Object.keys(R.nicknames).length > 500 || Object.entries(R.nicknames).some(([k, v]) => !/^[a-z]{1,40}$/.test(k) || typeof v !== 'string' || !/^[a-z]{1,40}$/.test(v))) rb('nicknames must be an object of lower-case nickname -> lower-case formal first name');
  }
}
if (bad.length) return reject(500, 'intake_misconfigured', bad);

// ---- request shape
if (!isObj(req.body)) return reject(400, 'validation_failed', ['body must be a JSON object']);
const b = req.body;
const errors = [];
const reqStr = (k, max) => { const v = b[k]; if (typeof v !== 'string' || !v.trim()) { errors.push(`${k} is required and must be a non-empty string`); return null; } if (v.trim().length > max) { errors.push(`${k} must be at most ${max} characters`); return null; } return v.trim(); };
const optStr = (k, max) => { const v = b[k]; if (v === undefined || v === null || v === '') return null; if (typeof v !== 'string') { errors.push(`${k} must be a string`); return null; } if (v.trim().length > max) { errors.push(`${k} must be at most ${max} characters`); return null; } return v.trim() || null; };
const email = reqStr('email', 254);
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email must be a valid email address');
const first_name = reqStr('first_name', 100), last_name = reqStr('last_name', 100), company = reqStr('company', 200);
const title = optStr('title', 200), phone = optStr('phone', 50), source = optStr('source', 100) || 'unknown';
const linkedin_url = optStr('linkedin_url', 500);
if (linkedin_url && !/^https?:\/\//i.test(linkedin_url)) errors.push('linkedin_url must start with http:// or https://');
let lead_id = null;
if (b.lead_id !== undefined && b.lead_id !== null && b.lead_id !== '') {
  if (typeof b.lead_id !== 'string' || !/^[A-Za-z0-9._:@+-]{1,254}$/.test(b.lead_id)) errors.push('lead_id must be 1-254 characters: letters, digits and . _ : @ + -');
  else lead_id = b.lead_id;
}
const RL = $('Lead Rules').first().json.rules;
for (const k of RL.require) if (b[k] === undefined || b[k] === null || b[k] === '') errors.push(`${k} is required`);
const custom = {};
for (const k of RL.custom_fields) {
  const v = b[k];
  if (v === undefined || v === null || v === '') continue;
  if (typeof v !== 'string') errors.push(`${k} must be a string`);
  else if (v.trim().length > 300) errors.push(`${k} must be at most 300 characters`);
  else custom[k] = v.trim();
}
if (errors.length) return reject(400, 'validation_failed', errors);
const domainOf = email.toLowerCase().split('@').pop();
if (RL.blocked_email_domains.includes(domainOf)) return reject(422, 'lead_rejected', [`email domain "${domainOf}" is not accepted`]);

// Identity of a lead when the caller supplies none: the normalised email itself. (No hashing: a short hash can collide and
// hand one person another person's cached result; the email cannot.)
const normEmail = email.toLowerCase();
return [{ json: { ok: true, lead_id: lead_id || ('email:' + normEmail), email: normEmail, first_name, last_name, company, title, phone, linkedin_url, source, custom, review_domain: RL.review_email_domains.includes(domainOf) } }];

const r = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
if (!r.error && r.statusCode === 201) return [{ json: { claim: 'owned' } }];
if (!r.error && r.statusCode === 409 && isObj(r.body) && isObj(r.body.existing)) {
  if (r.body.existing.status === 'completed') return [{ json: { claim: 'completed', record: isObj(r.body.existing.record) ? r.body.existing.record : {} } }];
  if (r.body.existing.status === 'processing') return [{ json: { claim: 'processing' } }];
}
return [{ json: { claim: 'unavailable', detail: r.error ? String(r.error.message || r.error).slice(0, 200) : `HTTP ${r.statusCode}` } }];

const L = $('Validate Request').first().json;
const rec = $json.record || {};
return [{ json: { http_status: 200, notifications: [], response_body: { status: 'already_processed', lead_id: L.lead_id, original_status: rec.status || null, crm_record_id: rec.crm_record_id || null, classification: rec.classification || null, processed_at: rec.processed_at || null } } }];

const RL_ = $('Lead Rules').first().json.rules, MT = RL_.matching;
const SUFFIX = new Set(['inc', 'incorporated', 'llc', 'ltd', 'limited', 'corp', 'corporation', 'co', 'company', 'gmbh', 'plc', 'lp', 'llp', 'sa', 'ag', 'bv', 'pty', ...RL_.company_suffixes]);
const PRE = new Set(['dr', 'mr', 'mrs', 'ms', 'miss', 'mx', 'prof', ...MT.name_prefixes]), POST = new Set(['jr', 'sr', 'ii', 'iii', 'iv', 'phd', 'md', ...MT.name_suffixes]);
const base = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const normCompany = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && SUFFIX.has(t[t.length - 1])) t.pop(); const k = t.join(' '); return Object.prototype.hasOwnProperty.call(MT.company_aliases, k) ? MT.company_aliases[k] : k; };
const UNKNOWN = new Set(MT.unknown_companies);
const unknownCompany = (s) => UNKNOWN.has(base(s)) || UNKNOWN.has(normCompany(s));
const firstOf = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && PRE.has(t[0])) t.shift(); return t[0] || ''; };
const lastOf = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && POST.has(t[t.length - 1])) t.pop(); return t.join(' '); };
const L = $('Validate Request').first().json;
const r = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
let status = 'failed', enriched = {};
if (!r.error && r.statusCode >= 200 && r.statusCode < 300 && isObj(r.body)) {
  if (r.body.found === true) { status = 'success'; enriched = { title: str(r.body.title), current_company: str(r.body.current_company), company_size: str(String(r.body.company_size ?? '')), industry: str(r.body.industry) }; }
  else if (r.body.found === false) status = 'not_found';
} else if (!r.error && r.statusCode === 404) status = 'not_found';
const mismatch = !!(enriched.current_company && !unknownCompany(L.company) && !unknownCompany(enriched.current_company) && normCompany(enriched.current_company) !== normCompany(L.company));
return [{ json: { enrichment_status: status, enriched, company_mismatch: mismatch } }];

const RL_ = $('Lead Rules').first().json.rules, MT = RL_.matching;
const SUFFIX = new Set(['inc', 'incorporated', 'llc', 'ltd', 'limited', 'corp', 'corporation', 'co', 'company', 'gmbh', 'plc', 'lp', 'llp', 'sa', 'ag', 'bv', 'pty', ...RL_.company_suffixes]);
const PRE = new Set(['dr', 'mr', 'mrs', 'ms', 'miss', 'mx', 'prof', ...MT.name_prefixes]), POST = new Set(['jr', 'sr', 'ii', 'iii', 'iv', 'phd', 'md', ...MT.name_suffixes]);
const base = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const normCompany = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && SUFFIX.has(t[t.length - 1])) t.pop(); const k = t.join(' '); return Object.prototype.hasOwnProperty.call(MT.company_aliases, k) ? MT.company_aliases[k] : k; };
const UNKNOWN = new Set(MT.unknown_companies);
const unknownCompany = (s) => UNKNOWN.has(base(s)) || UNKNOWN.has(normCompany(s));
const firstOf = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && PRE.has(t[0])) t.shift(); return t[0] || ''; };
const lastOf = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && POST.has(t[t.length - 1])) t.pop(); return t.join(' '); };
const C = $('CONFIG').first().json;
const L = $('Lead State').first().json;
const r = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const nick = { ...JSON.parse(C.NICKNAMES_JSON || '{}'), ...$('Lead Rules').first().json.rules.nicknames };

const fail = () => [{ json: { search_ok: false, classification: 'search_failed', action: C.SEARCH_FAILURE_MODE === 'reject' ? 'reject' : 'create', match_score: 0, candidate: null, exact_email: false, candidate_count: 0 } }];
if (r.error || !(r.statusCode >= 200 && r.statusCode < 300) || !isObj(r.body) || !Array.isArray(r.body.candidates)) return fail();

const lev = (a, b) => {
  if (a === b) return 0; if (!a.length) return b.length; if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  return prev[b.length];
};
const sim = (a, b) => { if (!a || !b) return 0; return 1 - lev(a, b) / Math.max(a.length, b.length); };
const first = (s) => { const f = firstOf(s); return nick[f] || f; };
const nameScore = (lf, ll, cf, cl) => {
  const a = [first(lf), lastOf(ll)], b = [first(cf), lastOf(cl)], w = MT.name_weights;
  if (!w) return sim(a.join(' '), b.join(' '));
  return (sim(a[0], b[0]) * w.first + sim(a[1], b[1]) * w.last) / (w.first + w.last);
};
const bestName = (cand) => { let v = nameScore(L.first_name, L.last_name, cand.first_name, cand.last_name); if (MT.swap_first_last) v = Math.max(v, nameScore(L.first_name, L.last_name, cand.last_name, cand.first_name)); return v; };
const wN = Number(C.NAME_WEIGHT), wC = Number(C.COMPANY_WEIGHT), wSum = wN + wC;

const lcomp = normCompany(L.company), lunknown = unknownCompany(L.company);
let best = null, n = 0;
for (const cand of r.body.candidates) {
  if (!isObj(cand) || cand.id === undefined || cand.id === null || cand.id === '') continue;   // unusable row
  n++;
  const emails = [cand.email, cand.secondary_email].filter((x) => typeof x === 'string').map((x) => x.trim().toLowerCase());
  if (emails.includes(L.email)) { if (!best || !best.exact_email) best = { candidate: cand, score: 1, exact_email: true }; continue; }
  if (best && best.exact_email) continue;
  const cs = lunknown || unknownCompany(cand.company) ? 0 : sim(lcomp, normCompany(cand.company));   // a placeholder company is never evidence
  const score = (bestName(cand) * wN + cs * wC) / wSum;
  if (!best || score > best.score) best = { candidate: cand, score, exact_email: false };
}
let classification = 'new_lead', action = 'create';
if (best) {
  if (best.exact_email) { classification = 'exact_match'; action = 'merge'; }
  else if (C.AUTO_MERGE_FUZZY !== false && best.score >= Number(C.AUTO_MERGE_THRESHOLD)) { classification = 'high_confidence'; action = 'merge'; }
  else if (best.score >= Number(C.REVIEW_THRESHOLD)) classification = 'possible_duplicate';
}
return [{ json: { search_ok: true, classification, action, match_score: best ? Math.round(best.score * 10000) / 10000 : 0, candidate: best ? best.candidate : null, exact_email: !!(best && best.exact_email), candidate_count: n } }];

const RL_ = $('Lead Rules').first().json.rules, MT = RL_.matching;
const SUFFIX = new Set(['inc', 'incorporated', 'llc', 'ltd', 'limited', 'corp', 'corporation', 'co', 'company', 'gmbh', 'plc', 'lp', 'llp', 'sa', 'ag', 'bv', 'pty', ...RL_.company_suffixes]);
const PRE = new Set(['dr', 'mr', 'mrs', 'ms', 'miss', 'mx', 'prof', ...MT.name_prefixes]), POST = new Set(['jr', 'sr', 'ii', 'iii', 'iv', 'phd', 'md', ...MT.name_suffixes]);
const base = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const normCompany = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && SUFFIX.has(t[t.length - 1])) t.pop(); const k = t.join(' '); return Object.prototype.hasOwnProperty.call(MT.company_aliases, k) ? MT.company_aliases[k] : k; };
const UNKNOWN = new Set(MT.unknown_companies);
const unknownCompany = (s) => UNKNOWN.has(base(s)) || UNKNOWN.has(normCompany(s));
const firstOf = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && PRE.has(t[0])) t.shift(); return t[0] || ''; };
const lastOf = (s) => { const t = base(s).split(' ').filter(Boolean); while (t.length > 1 && POST.has(t[t.length - 1])) t.pop(); return t.join(' '); };
const L = $('Lead State').first().json;
const S = $input.first().json;
const ex = S.candidate;
const E = L.enriched || {};
const incoming = { first_name: L.first_name, last_name: L.last_name, company: L.company, title: L.title || E.title || null, phone: L.phone, email: L.email, industry: E.industry || null, company_size: E.company_size || null, ...(L.custom || {}) };
const empty = (v) => v === undefined || v === null || String(v).trim() === '';
const same = (a, b, k) => (k === 'company' ? normCompany(a) === normCompany(b) : base(a) === base(b));
const patch = {}, conflicts = [];
for (const [k, v] of Object.entries(incoming)) {
  if (empty(v)) continue;
  if (empty(ex[k])) patch[k] = v;                                                    // fill the gap
  else if (!['industry', 'company_size'].includes(k) && !same(ex[k], v, k)) conflicts.push({ field: k, kept: ex[k], incoming: v });   // never overwrite
}
// A fuzzy match with a different email: keep the new address instead of dropping it.
if (!S.exact_email && !empty(ex.email) && !same(ex.email, L.email) && empty(ex.secondary_email)) patch.secondary_email = L.email;
return [{ json: { contact_id: ex.id, patch, conflicts, has_changes: Object.keys(patch).length > 0 } }];

const L = $('Lead State').first().json;
const S = $('Score Candidates').first().json;
const P = $('Build Merge Patch').first().json;
const r = $input.first().json;
const ok = !r.error && r.statusCode >= 200 && r.statusCode < 300;
if (ok) return [{ json: { write_ok: true, http_status: 200, review_reason: null, response_body: { status: 'merged', lead_id: L.lead_id, crm_record_id: String(P.contact_id), classification: S.classification, match_score: S.match_score, needs_review: false, fields_filled: Object.keys(P.patch), conflicts: P.conflicts, enrichment_status: L.enrichment_status, company_mismatch: L.company_mismatch } } }];
return [{ json: { write_ok: false, http_status: 502, response_body: { error: 'crm_write_failed', status: 'merge_failed', lead_id: L.lead_id, detail: r.error ? 'CRM unreachable' : `CRM update failed (HTTP ${r.statusCode})`, retry: true } } }];

const L = $('Lead State').first().json;
const S = $input.first().json;
const E = L.enriched || {};
const review_reason = S.classification === 'possible_duplicate' ? 'possible_duplicate' : (S.classification === 'search_failed' ? 'dedup_unchecked' : (L.review_domain ? 'review_domain' : null));
const payload = {
  ...(L.custom || {}),
  external_ref: L.lead_id,
  first_name: L.first_name, last_name: L.last_name, email: L.email, company: L.company,
  title: L.title || E.title || null, phone: L.phone, linkedin_url: L.linkedin_url, source: L.source,
  industry: E.industry || null, company_size: E.company_size || null,
  needs_review: review_reason !== null, review_reason,
  possible_duplicate_of: review_reason === 'possible_duplicate' && S.candidate ? S.candidate.id : null,
  match_score: review_reason === 'possible_duplicate' ? S.match_score : null,
  company_mismatch: L.company_mismatch, enriched_company: E.current_company || null
};
return [{ json: { payload } }];

const L = $('Lead State').first().json;
const S = $('Score Candidates').first().json;
const P = $('Build Create Payload').first().json.payload;
const r = $input.first().json;
const id = r.body && (r.body.id ?? null);
const ok = !r.error && r.statusCode >= 200 && r.statusCode < 300 && id !== null && id !== undefined && id !== '';
if (ok) return [{ json: { write_ok: true, http_status: 201, review_reason: P.review_reason, response_body: { status: 'created', lead_id: L.lead_id, crm_record_id: String(id), classification: S.classification, match_score: S.match_score, needs_review: P.needs_review, review_reason: P.review_reason, possible_duplicate_of: P.possible_duplicate_of, enrichment_status: L.enrichment_status, company_mismatch: L.company_mismatch } } }];
return [{ json: { write_ok: false, http_status: 502, response_body: { error: 'crm_write_failed', status: 'create_failed', lead_id: L.lead_id, detail: r.error ? 'CRM unreachable' : (r.statusCode >= 200 && r.statusCode < 300 ? 'CRM response had no id' : `CRM create failed (HTTP ${r.statusCode})`), retry: true } } }];

const o = $('Collect Outcome').first().json;
const L = $('Lead State').first().json;
const C = $('CONFIG').first().json;
const r = $input.first().json;
const storeOk = !r.error && r.statusCode >= 200 && r.statusCode < 300;
const body = { ...o.response_body };
const notes = [];
const id = L.lead_id;
if (o.write_ok) {
  if (!storeOk) { body.warnings = ['idempotency_record_not_saved']; notes.push(`Lead ${id} was written to the CRM (${body.crm_record_id}) but the lead store would not record it. A resubmit inside the window may create a duplicate; check the CRM.`); }
  if (body.needs_review && o.review_reason === 'possible_duplicate') notes.push(`Lead ${id} (CRM ${body.crm_record_id}) flagged as a possible duplicate of ${body.possible_duplicate_of}, similarity ${body.match_score}. Needs a human decision.`);
  if (body.needs_review && o.review_reason === 'dedup_unchecked') notes.push(`The CRM duplicate search failed, so lead ${id} (CRM ${body.crm_record_id}) was created flagged "dedup_unchecked". Please check it for duplicates.`);
  if (body.needs_review && o.review_reason === 'review_domain') notes.push(`Lead ${id} (CRM ${body.crm_record_id}) created flagged "review_domain": its email domain is on the review list.`);
  if (L.company_mismatch) notes.push(`Lead ${id}: submitted company "${L.company}" differs from the enriched current company "${L.enriched.current_company}". Possible job change; review recommended.`);
} else {
  notes.push(`Lead ${id}: ${body.error === 'crm_search_failed' ? 'CRM duplicate search failed, lead NOT created' : 'CRM write failed'} (${body.detail}). The caller was told to retry.`);
  if (!storeOk) notes.push(`Lead ${id}: could not release the lead-store claim; it will free itself after ${C.PROCESSING_TTL_SECONDS}s.`);
}
return [{ json: { http_status: o.http_status, response_body: body, notifications: notes.map((text) => ({ text })) } }];

const C = $('CONFIG').first().json;
const list = $input.first().json.notifications || [];
if (!C.SLACK_WEBHOOK_URL) return [];
return list.map((n) => ({ json: { text: '[Lead intake] ' + n.text } }));
